     1→/**
     2→ * Public API endpoint for the storefront zip code widget.
     3→ *
     4→ * Called from the merchant's storefront (Theme App Extension or custom JS)
     5→ * to check whether a zip code is serviceable.
     6→ *
     7→ * GET/POST /api/zip-check?shop=store.myshopify.com&zip=12345
     8→ *
     9→ * Response:
    10→ *   200 { allowed: true,  message: "...", eta: "...", zone: "..." }
    11→ *   200 { allowed: false, message: "..." }
    12→ *   400 { error: "Missing shop or zip parameter" }
    13→ *   404 { allowed: false, message: "Zip code not found", notFound: true }
    14→ */
    15→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
    16→import db from "../db.server";
    17→
    18→const CORS_HEADERS = {
    19→  "Access-Control-Allow-Origin": "*",
    20→  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    21→  "Access-Control-Allow-Headers": "Content-Type",
    22→  "Content-Type": "application/json",
    23→};
    24→
    25→async function handleZipCheck(shop: string | null, zip: string | null) {
    26→  if (!shop || !zip) {
    27→    return new Response(
    28→      JSON.stringify({ error: "Missing shop or zip parameter" }),
    29→      { status: 400, headers: CORS_HEADERS },
    30→    );
    31→  }
    32→
    33→  const normalizedZip = zip.trim().toUpperCase();
    34→
    35→  const zipRecord = await db.zipCode.findUnique({
    36→    where: { shop_zipCode: { shop, zipCode: normalizedZip } },
    37→  });
    38→
    39→  // Fetch widget config for custom messages (falls back to defaults)
    40→  const widgetConfig = await db.widgetConfig.findUnique({ where: { shop } });
    41→
    42→  // Fetch shop settings to determine default behavior for unlisted zip codes
    43→  const shopSettings = await db.shopSettings.findUnique({ where: { shop } });
    44→  const defaultBehavior = shopSettings?.defaultBehavior ?? "block";
    45→
    46→  if (!zipRecord || !zipRecord.isActive) {
    47→    const notFoundMsg =
    48→      widgetConfig?.notFoundMessage ??
    49→      "This zip code was not found in our system.";
    50→
    51→    // If the zip is simply not in the list (not inactive) and the merchant
    52→    // has set defaultBehavior to "allow", treat it as an allowed zip
    53→    if (!zipRecord && defaultBehavior === "allow") {
    54→      const successMsg =
    55→        widgetConfig?.successMessage ?? "We deliver to your area!";
    56→      return new Response(
    57→        JSON.stringify({
    58→          allowed: true,
    59→          message: successMsg,
    60→          eta: null,
    61→          zone: null,
    62→          showWaitlist: false,
    63→        }),
    64→        { status: 200, headers: CORS_HEADERS },
    65→      );
    66→    }
    67→
    68→    if (!zipRecord) {
    69→      return new Response(
    70→        JSON.stringify({
    71→          allowed: false,
    72→          message: notFoundMsg,
    73→          notFound: true,
    74→        }),
    75→        { status: 200, headers: CORS_HEADERS },
    76→      );
    77→    }
    78→
    79→    // Inactive zip — treat same as not found regardless of defaultBehavior
    80→    return new Response(
    81→      JSON.stringify({ allowed: false, message: notFoundMsg, notFound: true }),
    82→      { status: 200, headers: CORS_HEADERS },
    83→    );
    84→  }
    85→
    86→  if (zipRecord.type === "blocked") {
    87→    const errorMsg =
    88→      zipRecord.message ??
    89→      widgetConfig?.errorMessage ??
    90→      "Sorry, we don't deliver to this area yet.";
    91→
    92→    return new Response(
    93→      JSON.stringify({ allowed: false, message: errorMsg }),
    94→      { status: 200, headers: CORS_HEADERS },
    95→    );
    96→  }
    97→
    98→  // Allowed
    99→  const successMsg =
   100→    zipRecord.message ??
   101→    widgetConfig?.successMessage ??
   102→    "Great news! We deliver to your area.";
   103→
   104→  return new Response(
   105→    JSON.stringify({
   106→      allowed: true,
   107→      message: successMsg,
   108→      eta: widgetConfig?.showEta ? (zipRecord.eta ?? null) : null,
   109→      zone: widgetConfig?.showZone ? (zipRecord.zone ?? null) : null,
   110→      showWaitlist: false,
   111→    }),
   112→    { status: 200, headers: CORS_HEADERS },
   113→  );
   114→}
   115→
   116→// Handle GET requests: ?shop=...&zip=...
   117→export const loader = async ({ request }: LoaderFunctionArgs) => {
   118→  const url = new URL(request.url);
   119→
   120→  // Handle CORS preflight
   121→  if (request.method === "OPTIONS") {
   122→    return new Response(null, { status: 204, headers: CORS_HEADERS });
   123→  }
   124→
   125→  const shop = url.searchParams.get("shop");
   126→  const zip = url.searchParams.get("zip");
   127→  return handleZipCheck(shop, zip);
   128→};
   129→
   130→// Handle POST requests with JSON body: { shop, zip }
   131→export const action = async ({ request }: ActionFunctionArgs) => {
   132→  if (request.method === "OPTIONS") {
   133→    return new Response(null, { status: 204, headers: CORS_HEADERS });
   134→  }
   135→
   136→  let shop: string | null = null;
   137→  let zip: string | null = null;
   138→
   139→  try {
   140→    const body = await request.json();
   141→    shop = body?.shop ?? null;
   142→    zip = body?.zip ?? null;
   143→  } catch {
   144→    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
   145→      status: 400,
   146→      headers: CORS_HEADERS,
   147→    });
   148→  }
   149→
   150→  return handleZipCheck(shop, zip);
   151→};
