     1→import db from "./db.server";
     2→import {
     3→  ALL_PAID_PLANS,
     4→  PLAN_FREE,
     5→  getPlanTier,
     6→  PLAN_LIMITS,
     7→} from "./plans";
     8→
     9→export type PlanTier = "free" | "pro" | "ultimate";
    10→
    11→export interface ShopSubscription {
    12→  planId: string;
    13→  planTier: PlanTier;
    14→  billingInterval: string;
    15→  shopifySubscriptionId: string | null;
    16→  status: string;
    17→  trialEndsAt: Date | null;
    18→  limits: (typeof PLAN_LIMITS)[PlanTier];
    19→}
    20→
    21→/**
    22→ * Get (or create) the subscription record for a shop from the DB.
    23→ */
    24→export async function getShopSubscription(
    25→  shop: string,
    26→): Promise<ShopSubscription> {
    27→  let sub = await db.subscription.findUnique({ where: { shop } });
    28→
    29→  if (!sub) {
    30→    sub = await db.subscription.create({
    31→      data: {
    32→        shop,
    33→        planId: PLAN_FREE,
    34→        billingInterval: "monthly",
    35→        status: "active",
    36→      },
    37→    });
    38→  }
    39→
    40→  const planTier = getPlanTier(sub.planId) as PlanTier;
    41→  return {
    42→    planId: sub.planId,
    43→    planTier,
    44→    billingInterval: sub.billingInterval,
    45→    shopifySubscriptionId: sub.shopifySubscriptionId,
    46→    status: sub.status,
    47→    trialEndsAt: sub.trialEndsAt,
    48→    limits: PLAN_LIMITS[planTier],
    49→  };
    50→}
    51→
    52→/**
    53→ * Sync the subscription from Shopify billing check result into our DB.
    54→ * Returns the updated ShopSubscription.
    55→ */
    56→export async function syncSubscriptionFromShopify(
    57→  shop: string,
    58→  appSubscriptions: Array<{ id: string; name: string; status: string }>,
    59→): Promise<ShopSubscription> {
    60→  const activeSub = appSubscriptions.find((s) => s.status === "ACTIVE");
    61→
    62→  let planId = PLAN_FREE;
    63→  let billingInterval = "monthly";
    64→  let shopifySubscriptionId: string | null = null;
    65→  let status = "active";
    66→
    67→  if (activeSub) {
    68→    planId = activeSub.name;
    69→    shopifySubscriptionId = activeSub.id;
    70→    status = activeSub.status.toLowerCase();
    71→    billingInterval =
    72→      planId.toLowerCase().includes("annual") ? "annual" : "monthly";
    73→  }
    74→
    75→  const planTier = getPlanTier(planId) as PlanTier;
    76→
    77→  await db.subscription.upsert({
    78→    where: { shop },
    79→    create: {
    80→      shop,
    81→      planId,
    82→      billingInterval,
    83→      shopifySubscriptionId,
    84→      status,
    85→    },
    86→    update: {
    87→      planId,
    88→      billingInterval,
    89→      shopifySubscriptionId,
    90→      status,
    91→    },
    92→  });
    93→
    94→  return {
    95→    planId,
    96→    planTier,
    97→    billingInterval,
    98→    shopifySubscriptionId,
    99→    status,
   100→    trialEndsAt: null,
   101→    limits: PLAN_LIMITS[planTier],
   102→  };
   103→}
   104→
   105→/**
   106→ * Cancel subscription for a shop and revert to free.
   107→ */
   108→export async function cancelShopSubscription(shop: string): Promise<void> {
   109→  await db.subscription.upsert({
   110→    where: { shop },
   111→    create: {
   112→      shop,
   113→      planId: PLAN_FREE,
   114→      billingInterval: "monthly",
   115→      shopifySubscriptionId: null,
   116→      status: "active",
   117→    },
   118→    update: {
   119→      planId: PLAN_FREE,
   120→      billingInterval: "monthly",
   121→      shopifySubscriptionId: null,
   122→      status: "active",
   123→    },
   124→  });
   125→}
   126→
   127→/**
   128→ * Returns all Shopify plan names as strings for billing.check().
   129→ */
   130→export { ALL_PAID_PLANS };
   131→

