   100→// ─── Loader ───────────────────────────────────────────────────────────────────
   101→
   102→export const loader = async ({ request }: LoaderFunctionArgs) => {
   103→  const { session, billing } = await authenticate.admin(request);
   104→  const shop = session.shop;
   105→
   106→  try {
   107→    /* eslint-disable @typescript-eslint/no-explicit-any */
   108→    const billingCheck = await billing.check({
   109→      plans: ALL_PAID_PLANS as any,
   110→      isTest: process.env.NODE_ENV !== "production",
   111→    });
   112→    /* eslint-enable @typescript-eslint/no-explicit-any */
   113→    const subscription = await syncSubscriptionFromShopify(
   114→      shop,
   115→      billingCheck.appSubscriptions ?? [],
   116→    );
   117→    return { subscription };
   118→  } catch {
   119→    const subscription = await getShopSubscription(shop);
   120→    return { subscription };
   121→  }
   122→};
   123→
   124→// ─── Action ───────────────────────────────────────────────────────────────────
   125→
   126→export const action = async ({ request }: ActionFunctionArgs): Promise<
   127→  | { confirmationUrl: string }
   128→  | { error: string }
   129→  | { success: boolean; message: string }
   130→  | null
   131→> => {
   132→  const { session, billing } = await authenticate.admin(request);
   133→  const shop = session.shop;
   134→  const formData = await request.formData();
   135→  const intent = String(formData.get("intent"));
   136→
   137→  if (intent === "subscribe") {
   138→    const plan = String(formData.get("plan"));
   139→    const returnUrl = `${process.env.SHOPIFY_APP_URL}/app/pricing`;
   140→    try {
   141→      /* eslint-disable @typescript-eslint/no-explicit-any */
   142→      const confirmationUrl = await billing.request({
   143→        plan: plan as any,
   144→        isTest: process.env.NODE_ENV !== "production",
   145→        returnUrl,
   146→      }) as string;
   147→      /* eslint-enable @typescript-eslint/no-explicit-any */
   148→      return { confirmationUrl };
   149→    } catch {
   150→      return { error: "Failed to initiate subscription. Please try again." };
   151→    }
   152→  }
   153→
   154→  if (intent === "cancel") {
   155→    try {
   156→      const sub = await getShopSubscription(shop);
   157→      if (sub.shopifySubscriptionId) {
   158→        await billing.cancel({
   159→          subscriptionId: sub.shopifySubscriptionId,
   160→          isTest: process.env.NODE_ENV !== "production",
   161→          prorate: true,
   162→        });
   163→      }
   164→      await cancelShopSubscription(shop);
   165→      return {
   166→        success: true,
   167→        message: "Subscription cancelled. You are now on the Free plan.",
   168→      };
   169→    } catch {
   170→      return { error: "Failed to cancel subscription. Please try again." };
   171→    }
   172→  }
   173→
   174→  return null;
   175→};
