   177→// ─── Feature row ─────────────────────────────────────────────────────────────
   178→
   179→function PlanFeature({ feature }: { feature: string }) {
   180→  return (
   181→    <InlineStack gap="200" blockAlign="start" wrap={false}>
   182→      <Box>
   183→        <Icon source={CheckCircleIcon} tone="success" />
   184→      </Box>
   185→      <Text as="span" variant="bodyMd">
   186→        {feature}
   187→      </Text>
   188→    </InlineStack>
   189→  );
   190→}
   191→
   192→// ─── Plan card ────────────────────────────────────────────────────────────────
   193→
   194→type PlanCardProps = {
   195→  plan: (typeof PLANS_DATA)[keyof typeof PLANS_DATA];
   196→  isAnnual: boolean;
   197→  currentTier: string;
   198→  onSubscribe: (planName: string) => void;
   199→  onRequestCancel: () => void;
   200→  loadingPlan: string | null;
   201→};
   202→
   203→function PlanCard({
   204→  plan,
   205→  isAnnual,
   206→  currentTier,
   207→  onSubscribe,
   208→  onRequestCancel,
   209→  loadingPlan,
   210→}: PlanCardProps) {
   211→  const isCurrent = currentTier === plan.id;
   212→  const isBestValue = "bestValue" in plan && plan.bestValue;
   213→  const isCurrentPaid = currentTier !== "free";
   214→  const isDowngradeToFree = plan.id === "free" && isCurrentPaid;
   215→
   216→  // Tier order for upgrade/downgrade detection
   217→  const TIER_ORDER: Record<string, number> = { free: 0, pro: 1, ultimate: 2 };
   218→  const isUpgrade =
   219→    !isCurrent &&
   220→    plan.id !== "free" &&
   221→    (TIER_ORDER[plan.id] ?? 0) > (TIER_ORDER[currentTier] ?? 0);
   222→
   223→  const shopifyPlan = isAnnual
   224→    ? plan.shopifyPlanAnnual
   225→    : plan.shopifyPlanMonthly;
   226→
   227→  const displayPrice = isAnnual ? plan.annualMonthlyPrice : plan.monthlyPrice;
   228→
   229→  let buttonContent = "Start 14-day free trial";
   230→  if (isCurrent) {
   231→    buttonContent = "Current plan";
   232→  } else if (isDowngradeToFree) {
   233→    buttonContent = "Downgrade to Free";
   234→  } else if (isUpgrade) {
   235→    buttonContent = `Upgrade to ${plan.name}`;
   236→  } else if (!isCurrent && plan.id !== "free" && isCurrentPaid) {
   237→    // Paid → lower paid (e.g. Ultimate → Pro)
   238→    buttonContent = `Switch to ${plan.name}`;
   239→  }
   240→
   241→  const handleClick = () => {
   242→    if (isCurrent) return;
   243→    if (isDowngradeToFree) {
   244→      // Only cancellation flow (loses all paid features → needs confirmation)
   245→      onRequestCancel();
   246→    } else if (shopifyPlan) {
   247→      // All paid plan changes (upgrade or paid-to-paid switch) go via billing.request
   248→      onSubscribe(shopifyPlan);
   249→    }
   250→  };
   251→
   252→  const isThisLoading = loadingPlan === (shopifyPlan ?? "cancel");
   253→
   254→  return (
   255→    <Card>
   256→      <BlockStack gap="400">
   257→
   258→        {/* Plan name + badges */}
   259→        <BlockStack gap="100">
   260→          <InlineStack align="space-between" blockAlign="center">
   261→            <Text as="h3" variant="headingMd" fontWeight="bold">
   262→              {plan.name}
   263→            </Text>
   264→            <InlineStack gap="150">
   265→              {isBestValue && (
   266→                <Badge tone="info" icon={StarIcon}>
   267→                  Most popular
   268→                </Badge>
   269→              )}
   270→              {isCurrent && <Badge tone="success">Active</Badge>}
   271→            </InlineStack>
   272→          </InlineStack>
   273→          <Text as="p" variant="bodySm" tone="subdued">
   274→            {plan.description}
   275→          </Text>
   276→        </BlockStack>
   277→
   278→        <Divider />
   279→
   280→        {/* Price */}
   281→        <BlockStack gap="100">
   282→          {plan.monthlyPrice === 0 ? (
   283→            <>
   284→              <Text as="p" variant="headingXl" fontWeight="bold">
   285→                Free
   286→              </Text>
   287→              <Text as="p" variant="bodySm" tone="subdued">
   288→                forever
   289→              </Text>
   290→            </>
   291→          ) : (
   292→            <>
   293→              <InlineStack gap="100" blockAlign="baseline">
   294→                <Text as="p" variant="headingXl" fontWeight="bold">
   295→                  ${displayPrice}
   296→                </Text>
   297→                <Text as="p" variant="bodySm" tone="subdued">
   298→                  / month
   299→                </Text>
   300→              </InlineStack>
   301→              <Text as="p" variant="bodySm" tone="subdued">
   302→                {isAnnual
   303→                  ? `billed $${plan.annualPrice} / year`
   304→                  : `or $${plan.annualMonthlyPrice}/mo billed annually`}
   305→              </Text>
   306→            </>
   307→          )}
   308→        </BlockStack>
   309→
   310→        {/* CTA button */}
   311→        <Button
   312→          variant={isCurrent ? "secondary" : "primary"}
   313→          tone={isDowngradeToFree ? "critical" : undefined}
   314→          onClick={handleClick}
   315→          disabled={isCurrent}
   316→          loading={isThisLoading}
   317→          fullWidth
   318→        >
   319→          {buttonContent}
   320→        </Button>
   321→
   322→        <Divider />
   323→
   324→        {/* Features list */}
   325→        <BlockStack gap="300">
   326→          {plan.features.map((f) => (
   327→            <PlanFeature key={f} feature={f} />
   328→          ))}
   329→        </BlockStack>
   330→
   331→      </BlockStack>
   332→    </Card>
   333→  );
   334→}
