   437→
   438→            {/* Action feedback banners */}
   439→            {data && "error" in data && data.error && (
   440→              <Banner tone="critical">{String(data.error)}</Banner>
   441→            )}
   442→            {data && "success" in data && data.success && (
   443→              <Banner tone="success">
   444→                {data && "message" in data
   445→                  ? String(data.message)
   446→                  : "Plan updated successfully."}
   447→              </Banner>
   448→            )}
   449→
   450→            {/* Billing toggle — centred, fully Polaris */}
   451→            <BlockStack gap="200" inlineAlign="center">
   452→              <ButtonGroup variant="segmented">
   453→                <Button
   454→                  pressed={!isAnnual}
   455→                  onClick={() => setIsAnnual(false)}
   456→                >
   457→                  Monthly
   458→                </Button>
   459→                <Button
   460→                  pressed={isAnnual}
   461→                  onClick={() => setIsAnnual(true)}
   462→                >
   463→                  Annual · Save 20%
   464→                </Button>
   465→              </ButtonGroup>
   466→              {isAnnual && (
   467→                <Badge tone="success">You save up to 36% per year</Badge>
   468→              )}
   469→            </BlockStack>
   470→
   471→            {/* Plan cards */}
   472→            <InlineGrid columns={{ xs: 1, sm: 1, md: 3 }} gap="400">
